#include <iostream>
using namespace std;

int main() {
    int age = 20;
    double gpa = 3.5;
    char grade = 'A';
    cout << "int: " << sizeof(int) << " bytes" << endl;
    cout << "double: " << sizeof(double) << " bytes" << endl;
    cout << "char: " << sizeof(char) << " bytes" << endl;
    cout << "age uses " << sizeof(age) << " bytes" << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int a = 10, b = 20;
    cout << "a = " << a << ", b = " << b << endl;
    cout << "Is &a the same address as &a? " << (&a == &a) << endl;
    cout << "Are a and b in different places? " << (&a != &b) << endl;
    cout << "Address of a is a number? " << ((long long)&a > 0) << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int marks[5] = {70, 82, 91, 65, 88};
    cout << "One element: " << sizeof(marks[0]) << " bytes" << endl;
    cout << "Whole array: " << sizeof(marks) << " bytes" << endl;
    cout << "Elements: " << sizeof(marks) / sizeof(marks[0]) << endl;
    cout << "Last element is " << (long long)&marks[4] - (long long)&marks[0] << " bytes after the first" << endl;
    return 0;
}

